using HRM.Models;using HRM.Models.WorkPlanning;using HRM.WorkPlanning.Abstractions;using Microsoft.EntityFrameworkCore;
namespace HRM.WorkPlanning.Services;
public sealed class WorkforcePayrollExportService(IDbContextFactory<HrmTeContext> factory):IWorkforcePayrollExportService{public async Task<IReadOnlyList<WorkforcePayrollExportLine>>PrepareAsync(int org,string reference,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(reference)||reference.Trim().Length>128)throw new InvalidOperationException("An export reference of up to 128 characters is required.");await using var db=await factory.CreateDbContextAsync(ct);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);if(await db.WorkTimeLedgerEntries.AnyAsync(x=>x.OrganisationId==org&&x.PayrollExportReference==reference.Trim(),ct))throw new InvalidOperationException("That payroll export reference has already been finalized.");var rows=await db.WorkTimeLedgerEntries.Where(x=>x.OrganisationId==org&&x.Status=="Calculated"&&!x.IsPayrollFinalized).OrderBy(x=>x.Id).ToListAsync(ct);var exportedAt=DateTime.UtcNow;foreach(var row in rows){row.Status="Exported";row.PayrollExportReference=reference.Trim();row.PayrollExportedAtUtc=exportedAt;row.IsPayrollFinalized=true;}await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return rows.Select(x=>new WorkforcePayrollExportLine(x.Id,x.IndividualId,x.JobId,x.TimeCategory,x.ActualMinutes,x.CreditedMinutes,x.StartAt,x.EndAt)).ToList();}public async Task<long>CreateCorrectionAsync(WorkforcePayrollCorrection correction,CancellationToken ct=default){if(correction.ActualMinutes<0||correction.CreditedMinutes<0||string.IsNullOrWhiteSpace(correction.Reason))throw new InvalidOperationException("Correction minutes and reason are required.");await using var db=await factory.CreateDbContextAsync(ct);var original=await db.WorkTimeLedgerEntries.SingleOrDefaultAsync(x=>x.Id==correction.CorrectsLedgerEntryId&&x.OrganisationId==correction.OrganisationId,ct)??throw new InvalidOperationException("Ledger entry not found in this organisation.");if(!original.IsPayrollFinalized)throw new InvalidOperationException("Corrections are only needed after a ledger entry is finalized.");var row=new WorkTimeLedgerEntry{OrganisationId=original.OrganisationId,IndividualId=original.IndividualId,JobId=original.JobId,StartAt=original.StartAt,EndAt=original.EndAt,TimeCategory=original.TimeCategory,ActualMinutes=correction.ActualMinutes,CreditedMinutes=correction.CreditedMinutes,SourceReference=$"WS_CORRECTION:{original.Id}:{Guid.NewGuid():N}",Status="Calculated",CorrectsLedgerEntryId=original.Id,OperationLogId=correction.OperationLogId,CreatedAtUtc=DateTime.UtcNow};db.WorkTimeLedgerEntries.Add(row);await db.SaveChangesAsync(ct);return row.Id;}}
